import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int rows = nextInt(), cols = nextInt();
        long[] vals = new long[rows * cols];
        for (int i = 0; i < vals.length; i++) vals[i] = nextLong();
        StringBuilder sb = new StringBuilder();
        int found = 0;
        for (int i = 0; i < rows; i++)
            for (int j = 0; j < cols; j++) {
                long v = vals[i * cols + j];
                if (v == 0) continue;
                boolean ok = true;
                // Clip the radius-v square to the grid; skip the centre and the full square's corners.
                long x0 = Math.max(0, i - v), x1 = Math.min(rows, i + v + 1);
                long y0 = Math.max(0, j - v), y1 = Math.min(cols, j + v + 1);
                for (long x = x0; x < x1 && ok; x++)
                    for (long y = y0; y < y1; y++) {
                        if ((x == i && y == j) || (Math.abs(x - i) == v && Math.abs(y - j) == v)) continue;
                        if (vals[(int) (x * cols + y)] >= v) {
                            ok = false;
                            break;
                        }
                    }
                if (ok) {
                    found++;
                    sb.append('\n').append(i).append(' ').append(j);
                }
            }
        System.out.println(found + sb.toString());
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	rows, cols := int64(nextInt()), int64(nextInt())
	vals := make([]int64, rows*cols)
	for i := range vals {
		vals[i] = nextInt()
	}
	var out []byte
	found := 0
	for i := int64(0); i < rows; i++ {
		for j := int64(0); j < cols; j++ {
			v := vals[i*cols+j]
			if v == 0 {
				continue
			}
			ok := true
			// Clip the radius-v square to the grid; skip the centre and the full square's corners.
			for x := max(0, i-v); x < min(rows, i+v+1) && ok; x++ {
				for y := max(0, j-v); y < min(cols, j+v+1); y++ {
					if (x == i && y == j) || (abs(x-i) == v && abs(y-j) == v) {
						continue
					}
					if vals[x*cols+y] >= v {
						ok = false
						break
					}
				}
			}
			if ok {
				found++
				out = append(out, '\n')
				out = strconv.AppendInt(out, i, 10)
				out = append(out, ' ')
				out = strconv.AppendInt(out, j, 10)
			}
		}
	}
	fmt.Printf("%d%s\n", found, out)
}
